WITH base AS (SELECT id, store_id, product_id, ROUND(quantity, 0) quantity_rounded FROM inventory WHERE last_restock > '2023-10-01') SELECT id, product_id, quantity_rounded, AVG(quantity_rounded) OVER w_grp running_avg_quantity_rounded, SUM(quantity_rounded) OVER w_grp running_sum_quantity_rounded, MIN(quantity_rounded) OVER w_grp running_min_quantity_rounded, LAST_VALUE(quantity_rounded, TRUE) OVER w_grp_2 last_known_quantity_rounded FROM base WINDOW w_grp AS (PARTITION BY store_id, product_id ORDER BY quantity_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp_2 AS (PARTITION BY product_id, store_id ORDER BY quantity_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
